### 3. `test/nav-links.test.mts` (new file — the first behavioural test)

```ts
import { describe, expect, it } from 'vitest'
import { existsSync, readFileSync, readdirSync } from 'node:fs'
import { dirname, join, relative, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const CONFIG_FILE = join(ROOT, '.vitepress', 'config.mts')

/**
 * Pages that exist on disk but are intentionally NOT reachable from the nav/sidebar.
 * Each entry is a decision, not an oversight: adding one here is how we say
 * "this page stays unlisted". Anything else unlinked fails the suite.
 */
const UNLINKED_ALLOWLIST = [
  'delivery-contract.md',
  'features/autonomous-agents.md',
  'features/channel-creator.md',
  'features/workspaces-container-routing-review.md',
  'features/workspaces-settings-scope-review.md',
]

function toPosix(p: string): string {
  return p.split('\\').join('/')
}

/** Internal nav/sidebar targets. External URLs and pure anchors are out of scope. */
function internalLinks(): string[] {
  const source = readFileSync(CONFIG_FILE, 'utf8')
  return [...source.matchAll(/link:\s*['"]([^'"]+)['"]/g)]
    .map((m) => m[1])
    .filter((l) => !/^[a-z][a-z0-9+.-]*:/i.test(l) && !l.startsWith('#'))
}

/** The file on disk a VitePress link resolves to, or null. */
function pageFileFor(link: string): string | null {
  const clean = link.split('#')[0].split('?')[0]
  const rel = clean.replace(/^\/+/, '').replace(/\/+$/, '')
  const candidates = rel === '' ? ['index.md'] : [`${rel}.md`, `${rel}/index.md`]
  return candidates.find((c) => existsSync(join(ROOT, c))) ?? null
}

function markdownPages(dir = ROOT, acc: string[] = []): string[] {
  const skip = ['node_modules', '.git', '.codx', '.vitepress', 'tmp', 'dist']
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    if (skip.includes(entry.name)) continue
    const full = join(dir, entry.name)
    if (entry.isDirectory()) markdownPages(full, acc)
    else if (entry.name.endsWith('.md')) acc.push(toPosix(relative(ROOT, full)))
  }
  return acc
}

function linkedPages(): Set<string> {
  return new Set(
    internalLinks()
      .map((l) => pageFileFor(l))
      .filter((p): p is string => p !== null),
  )
}

describe('VitePress navigation', () => {
  it('parses the nav (guards against a silent zero-link parse)', () => {
    // If config.mts is reformatted and the parser stops matching, every other
    // assertion would pass vacuously. This is the canary.
    expect(internalLinks().length).toBeGreaterThan(30)
  })

  it('every nav/sidebar link points at a page that exists on disk', () => {
    const broken = internalLinks().filter((l) => pageFileFor(l) === null)
    expect(broken, `broken nav links: ${broken.join(', ')}`).toEqual([])
  })

  it('no page is silently unreachable from the nav', () => {
    const linked = linkedPages()
    const orphans = markdownPages().filter(
      (p) => !linked.has(p) && !UNLINKED_ALLOWLIST.includes(p),
    )
    expect(orphans, `unlinked pages: ${orphans.join(', ')}`).toEqual([])
  })

  it('the allow-list is exact: no stale entries', () => {
    const linked = linkedPages()
    const stale = UNLINKED_ALLOWLIST.filter(
      (p) => !existsSync(join(ROOT, p)) || linked.has(p),
    )
    expect(stale, `stale allow-list entries: ${stale.join(', ')}`).toEqual([])
  })
})
```

